// GEGENEREERD BESTAND — niet met de hand bewerken.
// Bron: data/geo-countries.js + shared/content/countries.data.mjs
// Genereer opnieuw met: node shared/content/build-shapes.mjs
// docs/openstaand/raad-het-land.md, migratiestap 1.
// Stand bij generatie: 225 van 230 pool-landen gekoppeld aan een contour
//   (5 via een handmatige alias, zie MANUAL_ALIASES in build-shapes.mjs).
// Pool-landen ZONDER contour (5): Réunion (re); Mayotte (yt); Martinique (mq); Guadeloupe (gp); French Guiana (gf)
//
// Contouren zonder tegenhanger in de pool (32) — gebiedsdelen en
// betwiste gebieden, horen niet in een quiz, vallen bewust af:
// Akrotiri Sovereign Base Area; Ashmore and Cartier Islands; Bajo Nuevo Bank (Petrel Is.); Baykonur Cosmodrome; Bermuda; Bir Tawil; Brazilian Island; British Indian Ocean Territory; Clipperton Island; Cook Islands; Coral Sea Islands; Cyprus No Mans Area; Dhekelia Sovereign Base Area; French Southern and Antarctic Lands; Heard Island and McDonald Islands; Indian Ocean Territories; Niue; Norfolk Island; Northern Cyprus; Pitcairn Islands; Saint Barthelemy; Saint Martin; Scarborough Reef; Serranilla Bank; Siachen Glacier; Somaliland; South Georgia and the Islands; Southern Patagonian Ice Field; Spratly Islands; US Naval Base Guantanamo Bay; United States Minor Outlying Islands; Wallis and Futuna
//
// PROPORTIONEEL, met twee bronnen (opdracht E + punt 1.14). De vorm komt uit
// data/geo-countries.js, de verhouding uit data/shapes.js of — als dat land
// daar niet in staat — uit microstate-aspects.data.mjs (geoBoundaries.org,
// zie die kop). Het geheel is met ÉÉN schaalfactor gecentreerd in het vak.
// Chili is daardoor een smalle streep en Rusland een brede band — het
// 100x100-vak blijft vierkant, alleen de inhoud vult nog maar één richting.
//
// UITGEREKT GEBLEVEN (6) — voor deze landen kent geen van beide bronnen
// een verhouding (build/world.geo.json is nooit gecommit, en ze staan ook
// niet in microstate-aspects.data.mjs). Ze dragen `stretched: true`; hun
// `aspect` staat rond de 1 en zegt niets:
// Aland (ax); Hong Kong S.A.R. (hk); Jersey (je); Macao S.A.R (mo); Saint Pierre and Miquelon (pm); Sint Maarten (sx)
//
// Per land:
//   iso2      landcode, zelfde conventie als de pool
//   shape     de "d"-waarde van een SVG <path>, viewBox "0 0 100 100"
//   box       [x, y, breedte, hoogte] — waar het land binnen dat vak staat
//   aspect    breedte / hoogte
//   center    [lon, lat] uit de brondata — de plek voor een wereldkaart
//             (besluit 53). GEEN extent: zie build-shapes.mjs, measure().
//   stretched alleen aanwezig als true (zie de lijst hierboven)
